SELECT MONTH(ss.sale_date) AS sale_month, CASE WHEN ss.units >= 36 THEN 'high' WHEN ss.units >= 12 THEN 'mid' ELSE 'low' END AS units_bucket, ROUND(AVG(i.quantity), 2) AS avg_quantity, MAX(i.quantity) - MIN(i.quantity) AS quantity_range FROM inventory i INNER JOIN store_sales ss ON i.store_id = ss.store_id AND i.product_id = ss.product_id WHERE ss.units IS NULL GROUP BY MONTH(ss.sale_date), CASE WHEN ss.units >= 36 THEN 'high' WHEN ss.units >= 12 THEN 'mid' ELSE 'low' END HAVING MAX(i.quantity) - MIN(i.quantity) > 39 ORDER BY quantity_range DESC, sale_month, units_bucket LIMIT 1;
